    'runwarn.PREP_INFINITE_NEUTRALIZED.fix':   'Corrige esas celdas en el archivo original para no perder esas ventas.',

    'runwarn.PREP_GAP_FILL_SKIPPED.title': 'Un producto tiene fechas imposibles',
